// Productive exercise bank (pure data): error-correction (FIX) and
// sentence-transformation (TRANSFORM) items, tagged by grammar unit.
// FIX item: { unit, bad, opts:[edit strings], a, ex, exId }
// TRANSFORM item: { unit, instruction, instructionId, original, answer, alts, tip, tipId }
export const FIX = [
  { unit: 1, bad: "Poverty remains a fundamental obstacle, and the unemployment makes it worse.", opts: ["the unemployment → unemployment","remains → remain","a fundamental → fundamental"], a: 0, ex: "Uncountable nouns used in a general sense (unemployment) take no article.", exId: "Kata benda tak terhitung yang bermakna umum (unemployment) tidak memakai artikel." },
  { unit: 1, bad: "She works as an European consultant on a prestigious project.", opts: ["an European → a European","a prestigious → an prestigious","consultant → consultants"], a: 0, ex: "'European' begins with a /j/ consonant sound, so it takes 'a', not 'an'.", exId: "'European' diawali bunyi konsonan /y/, jadi memakai 'a', bukan 'an'." },
  { unit: 1, bad: "The nurse said that honesty is best policy in the long run.", opts: ["best policy → the best policy","honesty → the honesty","the long run → a long run"], a: 0, ex: "A superlative such as 'best' requires the definite article 'the'.", exId: "Kata superlatif seperti 'best' memerlukan artikel pasti 'the'." },
  { unit: 1, bad: "She has become influential researcher in the field of neuroscience.", opts: ["influential researcher → an influential researcher","the field → a field","neuroscience → the neuroscience"], a: 0, ex: "A singular countable noun needs an article, and 'influential' begins with a vowel sound, so use 'an'.", exId: "Kata benda tunggal yang dapat dihitung memerlukan artikel, dan 'influential' diawali bunyi vokal, jadi gunakan 'an'." },
  { unit: 1, bad: "The scientist made important discovery that could transform renewable energy.", opts: ["important discovery → an important discovery","renewable energy → the renewable energy","The scientist → Scientist"], a: 0, ex: "A singular countable noun mentioned for the first time needs an indefinite article, and 'an' is used before the vowel sound in 'important'.", exId: "Kata benda tunggal yang dapat dihitung dan disebut pertama kali memerlukan artikel taktentu, dan 'an' dipakai sebelum bunyi vokal pada 'important'." },
  { unit: 2, bad: "The researcher gathered many informations before the conference.", opts: ["many informations → much information","gathered → gather","the conference → conference"], a: 0, ex: "'Information' is uncountable: no plural, and use 'much', not 'many'.", exId: "'Information' tak terhitung: tanpa jamak, dan pakai 'much', bukan 'many'." },
  { unit: 2, bad: "There were less participants than expected at the seminar.", opts: ["less participants → fewer participants","were → was","expected → expecting"], a: 0, ex: "Use 'fewer' with countable nouns (participants); 'less' is for uncountable.", exId: "Pakai 'fewer' untuk benda terhitung (participants); 'less' untuk tak terhitung." },
  { unit: 2, bad: "The survey collected a large amount of responses from participants.", opts: ["amount of responses → number of responses","responses → response","participants → participant"], a: 0, ex: "'Responses' is countable, so use 'number of' rather than 'amount of'.", exId: "'Responses' dapat dihitung, jadi gunakan 'number of', bukan 'amount of'." },
  { unit: 2, bad: "The new office did not have many furniture when it opened.", opts: ["many furniture → much furniture","furniture → furnitures","office → offices"], a: 0, ex: "'Furniture' is uncountable, so it takes 'much', not 'many'.", exId: "'Furniture' tidak dapat dihitung, jadi menggunakan 'much', bukan 'many'." },
  { unit: 2, bad: "The prosecutor presented very few evidence to support the serious accusation.", opts: ["few evidence → little evidence","the serious accusation → the serious accusations","presented → presents"], a: 0, ex: "'Evidence' is uncountable, so it takes the quantifier 'little', whereas 'few' is used only with countable nouns.", exId: "'Evidence' bersifat tak terhitung, sehingga memakai kuantitas 'little', sedangkan 'few' hanya dipakai dengan kata benda yang dapat dihitung." },
  { unit: 3, bad: "The outcome depends of the amount of funding allocated.", opts: ["depends of → depends on","the amount → an amount","allocated → allocating"], a: 0, ex: "The collocation is 'depend on', not 'depend of'.", exId: "Kolokasinya 'depend on', bukan 'depend of'." },
  { unit: 3, bad: "Residents strongly objected the controversial proposal.", opts: ["objected the → objected to","strongly → strong","controversial → controversy"], a: 0, ex: "'Object' takes 'to': object to something.", exId: "'Object' memakai 'to': object to sesuatu." },
  { unit: 3, bad: "The success of the project relies in the commitment of every stakeholder.", opts: ["relies in → relies on","success of → success in","commitment of → commitment for"], a: 0, ex: "The verb 'rely' takes the dependent preposition 'on', not 'in'.", exId: "Kata kerja 'rely' menggunakan preposisi 'on', bukan 'in'." },
  { unit: 3, bad: "The findings are consistent to previous studies conducted in the region.", opts: ["consistent to → consistent with","conducted in → conducted on","studies → study"], a: 0, ex: "The adjective 'consistent' is followed by the preposition 'with', not 'to'.", exId: "Kata sifat 'consistent' diikuti preposisi 'with', bukan 'to'." },
  { unit: 3, bad: "The company is renowned of its commitment to sustainability.", opts: ["renowned of → renowned for","commitment to → commitment for","is → was"], a: 0, ex: "The adjective 'renowned' takes the dependent preposition 'for', not 'of'.", exId: "Kata sifat 'renowned' menggunakan preposisi bergantung 'for', bukan 'of'." },
  { unit: 4, bad: "This method is far more cheaper than the previous one.", opts: ["more cheaper → cheaper","more efficient → efficienter","than → then"], a: 0, ex: "Never use 'more' with an -er comparative; 'cheaper' is already comparative.", exId: "Jangan pakai 'more' dengan bentuk -er; 'cheaper' sudah komparatif." },
  { unit: 4, bad: "It was the most cheapest option available to the committee.", opts: ["most cheapest → cheapest","available → availabler","option → options"], a: 0, ex: "Don't combine 'most' with an -est superlative; use 'the cheapest'.", exId: "Jangan gabungkan 'most' dengan -est; pakai 'the cheapest'." },
  { unit: 4, bad: "The new model performs significantly better as the older version in every test.", opts: ["as → than","better → more better","performs → perform"], a: 0, ex: "Comparatives are followed by 'than', not 'as', so 'better' must be paired with 'than'.", exId: "Bentuk komparatif diikuti oleh 'than', bukan 'as', sehingga 'better' harus dipasangkan dengan 'than'." },
  { unit: 4, bad: "Of all the submitted proposals, this one is by far the more innovative.", opts: ["more → most","the → a","by far → by much"], a: 0, ex: "When comparing one item against an entire group, use the superlative 'the most', not the comparative 'more'.", exId: "Ketika membandingkan satu hal dengan seluruh kelompok, gunakan bentuk superlatif 'the most', bukan komparatif 'more'." },
  { unit: 4, bad: "The upgraded software is considerably more efficient than the previous version, although it is noticeably expensiver.", opts: ["expensiver → more expensive","more efficient → most efficient","than → then"], a: 0, ex: "Adjectives of two or more syllables such as \"expensive\" form the comparative with \"more,\" not the ending \"-er.\"", exId: "Kata sifat yang terdiri dari dua suku kata atau lebih seperti \"expensive\" membentuk komparatif dengan \"more,\" bukan akhiran \"-er.\"" },
  { unit: 5, bad: "Each of the candidates were interviewed by a senior panel.", opts: ["were → was","candidates → candidate","interviewed → interviewing"], a: 0, ex: "'Each of ...' is singular, so the verb is 'was'.", exId: "'Each of ...' bersifat tunggal, jadi kata kerjanya 'was'." },
  { unit: 5, bad: "The number of applicants have risen substantially this year.", opts: ["have → has","applicants → applicant","risen → rose"], a: 0, ex: "'The number of ...' is singular → 'has risen'.", exId: "'The number of ...' tunggal → 'has risen'." },
  { unit: 5, bad: "There is several factors that influence the final outcome.", opts: ["is → are","factors → factor","influence → influences"], a: 0, ex: "The plural subject 'several factors' requires the plural verb 'are', not 'is'.", exId: "Subjek jamak 'several factors' memerlukan kata kerja jamak 'are', bukan 'is'." },
  { unit: 5, bad: "Economics are a discipline that demands strong analytical skills.", opts: ["are → is","demands → demand","discipline → disciplines"], a: 0, ex: "Academic subjects like 'economics' are treated as singular, so they take the singular verb 'is'.", exId: "Mata pelajaran akademik seperti 'economics' dianggap tunggal, sehingga memakai kata kerja tunggal 'is'." },
  { unit: 5, bad: "The list of approved suppliers were circulated to every department last week.", opts: ["were → was","were → have been","circulated → circulate"], a: 0, ex: "The subject is the singular noun \"list,\" so the verb must be singular (\"was\"); the phrase \"of approved suppliers\" does not affect the agreement.", exId: "Subjeknya adalah kata benda tunggal \"list,\" sehingga kata kerjanya harus tunggal (\"was\"); frasa \"of approved suppliers\" tidak memengaruhi kesesuaian." },
  { unit: 6, bad: "By the time the auditors arrived, the manager already left.", opts: ["already left → had already left","arrived → had arrived","the manager → a manager"], a: 0, ex: "An earlier past action before another past event takes the past perfect: 'had left'.", exId: "Tindakan lampau sebelum peristiwa lampau lain memakai past perfect: 'had left'." },
  { unit: 6, bad: "While she was reviewing the data, the system was crashing suddenly.", opts: ["was crashing → crashed","was reviewing → reviewed","the data → data"], a: 0, ex: "A sudden, completed action uses the past simple; the ongoing action stays continuous.", exId: "Tindakan mendadak yang selesai memakai past simple; yang berlangsung tetap continuous." },
  { unit: 6, bad: "When she was a student, she would live in a remote mountain village.", opts: ["would live → used to live","was → had been","remote → more remote"], a: 0, ex: "'Would' cannot describe past states; a lasting past situation like living somewhere needs 'used to live'.", exId: "'Would' tidak bisa menggambarkan keadaan lampau; situasi lampau yang menetap seperti tinggal di suatu tempat memerlukan 'used to live'." },
  { unit: 6, bad: "The engineers finally repaired the turbine that broke down the previous week.", opts: ["broke down → had broken down","repaired → were repairing","finally → final"], a: 0, ex: "The breakdown happened before the repair, so the earlier event needs the past perfect 'had broken down'.", exId: "Kerusakan terjadi sebelum perbaikan, sehingga peristiwa yang lebih awal memerlukan past perfect 'had broken down'." },
  { unit: 6, bad: "When the fire alarm rang, the technicians have already evacuated the building.", opts: ["have already evacuated → had already evacuated","rang → was ringing","evacuated → evacuating"], a: 0, ex: "An action completed before another past event takes the past perfect (\"had evacuated\"), not the present perfect (\"have evacuated\").", exId: "Tindakan yang selesai sebelum peristiwa lampau lainnya menggunakan past perfect (\"had evacuated\"), bukan present perfect (\"have evacuated\")." },
  { unit: 7, bad: "She is knowing the answer because she has studied the topic thoroughly.", opts: ["is knowing → knows","has studied → studied","thoroughly → thorough"], a: 0, ex: "'Know' is a stative verb and is not used in the continuous.", exId: "'Know' kata kerja stative, tidak dipakai dalam bentuk continuous." },
  { unit: 7, bad: "Prices have risen since three years, which worries economists.", opts: ["since → for","have risen → have rise","worries → worry"], a: 0, ex: "Use 'for' with a period of time (three years); 'since' takes a point in time.", exId: "Pakai 'for' untuk durasi (tiga tahun); 'since' untuk titik waktu." },
  { unit: 7, bad: "The new regulation is seeming unnecessarily complex to most small businesses.", opts: ["is seeming → seems","unnecessarily → unnecessary","is seeming → is seemed"], a: 0, ex: "Seem is a stative verb describing a state of perception, so it takes the present simple, not the present continuous.", exId: "'Seem' adalah kata kerja statis yang menyatakan keadaan/persepsi, sehingga memakai present simple, bukan present continuous." },
  { unit: 7, bad: "The scientist has published her groundbreaking paper last month, and it has already been cited widely.", opts: ["has published → published","last month → since last month","has been cited → is cited"], a: 0, ex: "A finished-time marker like 'last month' requires the past simple, not the present perfect.", exId: "Penanda waktu yang sudah selesai seperti 'last month' menuntut past simple, bukan present perfect." },
  { unit: 7, bad: "The committee is meeting every Monday to review the annual budget.", opts: ["is meeting → meets","is meeting → will meet","to review → for review"], a: 0, ex: "A regular, scheduled routine (signalled by 'every Monday') takes the present simple, not the present continuous.", exId: "Rutinitas yang teratur dan terjadwal (ditandai dengan 'every Monday') memakai present simple, bukan present continuous." },
  { unit: 8, bad: "By 2030, the company will finish constructing the new facility.", opts: ["will finish → will have finished","constructing → to construct","the new → a new"], a: 0, ex: "'By + future time' with a completed action takes the future perfect: 'will have finished'.", exId: "'By + waktu depan' dengan tindakan selesai memakai future perfect: 'will have finished'." },
  { unit: 8, bad: "I can't meet at noon; this time tomorrow I will fly to Jakarta.", opts: ["will fly → will be flying","can't → can not able","at noon → in noon"], a: 0, ex: "An action in progress at a future moment uses the future continuous: 'will be flying'.", exId: "Tindakan yang berlangsung pada saat di masa depan memakai future continuous: 'will be flying'." },
  { unit: 8, bad: "By the time the inspectors arrive, the staff will dispose of all the hazardous waste.", opts: ["will dispose → will have disposed","arrive → will arrive","will dispose → dispose"], a: 0, ex: "Use the future perfect (will have + past participle) for an action completed before another future point marked by 'by the time'.", exId: "Gunakan future perfect (will have + past participle) untuk tindakan yang selesai sebelum titik masa depan lain yang ditandai 'by the time'." },
  { unit: 8, bad: "By December, the researchers will be collecting data for eighteen months.", opts: ["will be collecting → will have been collecting","for → since","will be collecting → are collecting"], a: 0, ex: "With 'by + future time' plus a duration ('for eighteen months'), use the future perfect continuous (will have been + -ing).", exId: "Dengan 'by + waktu depan' ditambah durasi ('for eighteen months'), gunakan future perfect continuous (will have been + -ing)." },
  { unit: 8, bad: "As soon as the government will announce the reform, markets will respond immediately.", opts: ["will announce → announces","will announce → will have announced","will respond → responds"], a: 0, ex: "In a future time clause introduced by 'as soon as' (also 'when, before, until, after'), use the present simple, not 'will'; the main clause keeps 'will'.", exId: "Dalam anak kalimat waktu yang diawali 'as soon as' (juga 'when, before, until, after'), gunakan present simple, bukan 'will'; induk kalimatnya tetap memakai 'will'." },
  { unit: 9, bad: "The results were analysed by the team, and a report wrote last week.", opts: ["a report wrote → a report was written","were analysed → were analyse","last week → in last week"], a: 0, ex: "The passive needs 'be + past participle': 'was written'.", exId: "Bentuk pasif butuh 'be + past participle': 'was written'." },
  { unit: 9, bad: "The regulations must be complied, or the firm will face penalties.", opts: ["must be complied → must be complied with","will face → will faced","penalties → penalty"], a: 0, ex: "'Comply with' keeps its preposition in the passive: 'be complied with'.", exId: "'Comply with' mempertahankan preposisinya dalam bentuk pasif: 'be complied with'." },
  { unit: 9, bad: "The new safety protocol has been implement across all branches since January.", opts: ["has been implement → has been implemented","since → for","has been implement → has implemented"], a: 0, ex: "The passive needs be + past participle, so after 'has been' use 'implemented', not the base form 'implement'.", exId: "Kalimat pasif memerlukan be + past participle, jadi setelah 'has been' gunakan 'implemented', bukan bentuk dasar 'implement'." },
  { unit: 9, bad: "The damaged bridge is currently repairing by a specialist contractor.", opts: ["is currently repairing → is currently being repaired","is currently repairing → is currently repaired","is currently repairing → has currently repaired"], a: 0, ex: "For an action in progress, use the present continuous passive: is/are + being + past participle.", exId: "Untuk tindakan yang sedang berlangsung, gunakan present continuous passive: is/are + being + past participle." },
  { unit: 9, bad: "The confidential findings need to publish before the conference.", opts: ["to publish → to be published","need → needs","to publish → to be publish"], a: 0, ex: "After 'need to', a passive meaning requires 'to be + past participle' ('to be published'), because the findings receive the action rather than perform it.", exId: "Setelah 'need to', makna pasif memerlukan 'to be + past participle' ('to be published'), karena temuan itu dikenai tindakan, bukan melakukannya." },
  { unit: 10, bad: "If the government would invest more, poverty would decline significantly.", opts: ["would invest → invested","would decline → declines","significantly → significant"], a: 0, ex: "In a second conditional, the if-clause uses the past simple, not 'would'.", exId: "Dalam conditional tipe 2, klausa if memakai past simple, bukan 'would'." },
  { unit: 10, bad: "If they had acted sooner, the crisis would be avoided entirely.", opts: ["would be avoided → would have been avoided","had acted → have acted","entirely → entire"], a: 0, ex: "A third-conditional result uses 'would have + past participle'.", exId: "Hasil conditional tipe 3 memakai 'would have + past participle'." },
  { unit: 10, bad: "If she had submitted the application on time, she will have secured the scholarship.", opts: ["will have secured → would have secured","had submitted → submitted","had submitted → had been submitting"], a: 0, ex: "A third conditional requires 'would have + past participle' in the result clause, not 'will have'.", exId: "Kalimat pengandaian ketiga membutuhkan 'would have + past participle' pada klausa hasil, bukan 'will have'." },
  { unit: 10, bad: "If he had specialised in engineering, he would have been the chief designer now.", opts: ["would have been → would be","had specialised → specialised","had specialised → would specialise"], a: 0, ex: "The word 'now' signals a present result, so a mixed conditional needs 'would be', not 'would have been'.", exId: "Kata 'now' menandakan hasil di masa kini, jadi kondisional campuran memerlukan 'would be', bukan 'would have been'." },
  { unit: 10, bad: "If the researchers had shared their data earlier, other teams would avoided months of duplicated effort.", opts: ["would avoided → would have avoided","had shared → shared","had shared → would share"], a: 0, ex: "This is a third conditional, so the main clause needs \"would have + past participle\": \"would avoided\" becomes \"would have avoided.\"", exId: "Ini adalah conditional ketiga, jadi klausa utama membutuhkan \"would have + past participle\": \"would avoided\" menjadi \"would have avoided.\"" },
  { unit: 11, bad: "The lab is empty, so the experiment must had finished already.", opts: ["must had finished → must have finished","the experiment → an experiment","already → yet"], a: 0, ex: "A confident deduction about the past uses 'must have + past participle'.", exId: "Dugaan yakin tentang masa lalu memakai 'must have + past participle'." },
  { unit: 11, bad: "You should have to double-check the figures before submitting them.", opts: ["should have to → should","the figures → figures","submitting → submit"], a: 0, ex: "'Should' is a modal and is not followed by 'have to'; use 'should double-check'.", exId: "'Should' adalah modal dan tak diikuti 'have to'; pakai 'should double-check'." },
  { unit: 11, bad: "The negotiations collapsed, but with better mediation the outcome might been more favourable.", opts: ["might been → might have been","might been → might be","collapsed → had collapsed"], a: 0, ex: "Speculation about the past uses 'might have + past participle', so 'been' needs the auxiliary 'have'.", exId: "Spekulasi tentang masa lampau menggunakan 'might have + past participle', jadi 'been' membutuhkan kata bantu 'have'." },
  { unit: 11, bad: "Within a decade, advanced robots will can perform delicate surgical procedures.", opts: ["will can → will be able to","will can → will could","perform → to perform"], a: 0, ex: "Two modal verbs cannot be combined, so future ability is expressed with 'will be able to'.", exId: "Dua kata kerja modal tidak dapat digabungkan, jadi kemampuan di masa depan dinyatakan dengan 'will be able to'." },
  { unit: 11, bad: "The corridor lights are still on, so the technicians must leave in a hurry.", opts: ["must leave → must have left","must leave → had to leave","must leave → must be leaving"], a: 0, ex: "A confident deduction about a completed past action uses \"must have + past participle,\" so \"must leave\" becomes \"must have left.\"", exId: "Deduksi yang meyakinkan tentang tindakan lampau yang sudah selesai menggunakan \"must have + past participle,\" jadi \"must leave\" menjadi \"must have left.\"" },
  { unit: 12, bad: "The scientist which led the study won a prestigious award.", opts: ["which → who","led → lead","a prestigious → prestigious"], a: 0, ex: "Use 'who' (not 'which') to refer to people.", exId: "Pakai 'who' (bukan 'which') untuk merujuk orang." },
  { unit: 12, bad: "The report, that was published yesterday, contains substantial errors.", opts: ["that → which","was published → published","substantial → substantially"], a: 0, ex: "A non-defining clause (set off by commas) uses 'which', not 'that'.", exId: "Klausa non-defining (dipisah koma) memakai 'which', bukan 'that'." },
  { unit: 12, bad: "The novelist who latest book topped the bestseller list will give a public lecture.", opts: ["who → whose","who → who's","who → which"], a: 0, ex: "'Whose' shows possession, connecting the novelist to the book; 'who' cannot act as a possessive.", exId: "'Whose' menunjukkan kepemilikan, menghubungkan novelis dengan buku; 'who' tidak dapat berfungsi sebagai kata ganti kepemilikan." },
  { unit: 12, bad: "The bridge which the engineers reinforced it withstood the powerful storm.", opts: ["reinforced it → reinforced","which → where","which → in which"], a: 0, ex: "The relative pronoun 'which' already stands in for the object, so the extra pronoun 'it' must be deleted.", exId: "Kata ganti relatif 'which' sudah menggantikan objek, jadi kata ganti tambahan 'it' harus dihapus." },
  { unit: 12, bad: "The laboratory which the samples were stored was severely damaged by the flood.", opts: ["which → where","which → in that","which → whose"], a: 0, ex: "\"Where\" is the correct relative adverb for a place, so \"which\" becomes \"where\" (the samples were stored in the laboratory).", exId: "\"Where\" adalah kata keterangan relatif yang tepat untuk tempat, jadi \"which\" menjadi \"where\" (sampel disimpan di laboratorium itu)." },
  { unit: 13, bad: "Despite the data was limited, the researcher reached a firm conclusion.", opts: ["Despite → Although","was limited → limited","reached → reach"], a: 0, ex: "'Despite' is followed by a noun/-ing; before a full clause use 'Although'.", exId: "'Despite' diikuti kata benda/-ing; sebelum klausa lengkap pakai 'Although'." },
  { unit: 13, bad: "The results were conclusive, the team celebrated immediately.", opts: ["conclusive, the → conclusive, so the","were → was","immediately → immediate"], a: 0, ex: "Two independent clauses can't be joined by a comma alone (comma splice); add a conjunction.", exId: "Dua klausa independen tak bisa digabung hanya dengan koma (comma splice); tambahkan konjungsi." },
  { unit: 13, bad: "Because of the subsidy was withdrawn, several manufacturers relocated overseas.", opts: ["Because of → Because","relocated → had relocated","several → the several"], a: 0, ex: "'Because of' is a preposition used before a noun; before a full clause use the conjunction 'because'.", exId: "'Because of' adalah preposisi yang dipakai sebelum kata benda; sebelum klausa lengkap gunakan konjungsi 'because'." },
  { unit: 13, bad: "Although the evidence was compelling, but the jury remained unconvinced.", opts: ["but the jury → the jury","Although → Despite","remained → remaining"], a: 0, ex: "English does not pair a subordinator like 'although' with a coordinator like 'but' in the same sentence; drop the 'but'.", exId: "Bahasa Inggris tidak memasangkan subordinator seperti 'although' dengan koordinator 'but' dalam satu kalimat; hapus 'but'." },
  { unit: 13, bad: "The chair extended the meeting in order to the committee could reach a consensus.", opts: ["in order to → so that","in order to → so as to","in order to → in order for"], a: 0, ex: "Use 'so that' to introduce a purpose clause that has its own subject and modal verb, whereas 'in order to' must be followed directly by a bare infinitive.", exId: "Gunakan 'so that' untuk memperkenalkan klausa tujuan yang memiliki subjek dan kata kerja modal sendiri, sedangkan 'in order to' harus langsung diikuti oleh infinitif dasar." },
  { unit: 14, bad: "The board recommended to postpone the controversial merger.", opts: ["to postpone → postponing","recommended → recommend","the controversial → controversial"], a: 0, ex: "'Recommend' is followed by the gerund (-ing): 'recommend postponing'.", exId: "'Recommend' diikuti gerund (-ing): 'recommend postponing'." },
  { unit: 14, bad: "They decided investing in renewable infrastructure this year.", opts: ["investing → to invest","decided → decide","renewable → renew"], a: 0, ex: "'Decide' is followed by the infinitive: 'decide to invest'.", exId: "'Decide' diikuti infinitive: 'decide to invest'." },
  { unit: 14, bad: "The negotiators could not avoid to compromise on several key clauses.", opts: ["avoid to compromise → avoid compromising","could not → could not to","on several → in several"], a: 0, ex: "The verb 'avoid' is always followed by a gerund (-ing), never by a to-infinitive.", exId: "Kata kerja 'avoid' selalu diikuti gerund (-ing), bukan to-infinitive." },
  { unit: 14, bad: "She is committed to improve the accuracy of the forecasting model.", opts: ["to improve → to improving","committed → commits","the accuracy → accuracy"], a: 0, ex: "In 'be committed to', 'to' is a preposition, so it must be followed by a gerund ('improving'), not a base verb.", exId: "Pada 'be committed to', 'to' adalah preposisi, sehingga harus diikuti gerund ('improving'), bukan kata kerja dasar." },
  { unit: 14, bad: "The committee looks forward to receive the final audit report next week.", opts: ["to receive → to receiving","looks forward to → looks forward","to receive → receiving"], a: 0, ex: "After the phrasal verb 'look forward to', the word 'to' is a preposition, so it must be followed by a gerund, not a bare infinitive.", exId: "Setelah frasa kata kerja 'look forward to', kata 'to' adalah preposisi, sehingga harus diikuti oleh gerund, bukan infinitif dasar." },
  { unit: 15, bad: "She said that she is exhausted after the demanding negotiation.", opts: ["is → was","said that → said to","demanding → demanded"], a: 0, ex: "After 'said' (past), the present 'is' backshifts to 'was'.", exId: "Setelah 'said' (lampau), 'is' bergeser menjadi 'was'." },
  { unit: 15, bad: "He asked me where did I find the reliable data.", opts: ["where did I find → where I had found","asked me → asked to me","reliable → reliably"], a: 0, ex: "Reported questions use statement word order (no 'did'), with backshift.", exId: "Pertanyaan tak langsung memakai urutan pernyataan (tanpa 'did'), dengan backshift." },
  { unit: 15, bad: "During the briefing, she told that the merger would be finalised soon.", opts: ["told → said","would be → will be","the merger → merger"], a: 0, ex: "'Tell' needs a personal object (tell someone); with no object here, use 'said'.", exId: "'Tell' memerlukan objek orang (tell someone); karena tidak ada objek di sini, gunakan 'said'." },
  { unit: 15, bad: "Last week she said that she would present her results tomorrow.", opts: ["tomorrow → the following day","would present → will present","her results → the results"], a: 0, ex: "Because the report comes later than the speech ('last week'), the time word 'tomorrow' shifts to 'the following day'.", exId: "Karena pelaporan terjadi setelah ucapan ('last week'), kata waktu 'tomorrow' berubah menjadi 'the following day'." },
  { unit: 15, bad: "The supervisor told the technicians don't operate the machine without training.", opts: ["don't operate → not to operate","don't operate → to don't operate","don't operate → not operate"], a: 0, ex: "A reported negative command uses 'not to + infinitive', so 'not to operate' replaces the direct imperative 'don't operate'.", exId: "Perintah negatif dalam kalimat tidak langsung menggunakan 'not to + infinitif', sehingga 'not to operate' menggantikan perintah langsung 'don't operate'." },
  { unit: 16, bad: "The plan was inexpensive, however it proved unworkable in practice.", opts: ["inexpensive, however it → inexpensive; however, it","proved → proof","in practice → in practical"], a: 0, ex: "'However' joining two clauses needs a semicolon before it and a comma after.", exId: "'However' yang menghubungkan dua klausa butuh titik koma sebelum dan koma sesudah." },
  { unit: 16, bad: "Despite of the heavy rain, the outdoor event continued as planned.", opts: ["Despite of → Despite","continued → continue","as planned → as planning"], a: 0, ex: "It is 'despite' (no 'of') or 'in spite of'.", exId: "Yang benar 'despite' (tanpa 'of') atau 'in spite of'." },
  { unit: 16, bad: "Despite the regulator raised objections, the acquisition proceeded.", opts: ["Despite → Although","proceeded → had proceeded","the acquisition → acquisition"], a: 0, ex: "'Despite' is a preposition and cannot introduce a full clause, so the conjunction 'although' is needed before a subject and verb.", exId: "'Despite' adalah preposisi dan tidak dapat mengawali klausa lengkap, sehingga konjungsi 'although' diperlukan sebelum subjek dan kata kerja." },
  { unit: 16, bad: "Although the funding was severely limited, but the team achieved remarkable results.", opts: ["achieved → had achieved","but the team → the team","Although → Despite"], a: 1, ex: "English does not use 'although' and 'but' together to link the same two clauses, so only one connector should remain.", exId: "Bahasa Inggris tidak menggunakan 'although' dan 'but' bersamaan untuk menghubungkan dua klausa yang sama, jadi hanya satu penghubung yang dipertahankan." },
  { unit: 16, bad: "The costs escalated rapidly, therefore the project was abandoned.", opts: ["\"rapidly, therefore\" → \"rapidly; therefore,\"","\"therefore the\" → \"therefore, the\"","\"therefore\" → \"however,\""], a: 0, ex: "'Therefore' is a conjunctive adverb, so the two independent clauses need a semicolon (or full stop) before it, not a comma.", exId: "'Therefore' adalah kata keterangan penghubung (conjunctive adverb), sehingga dua klausa lengkap harus dipisahkan dengan titik koma (atau titik) sebelumnya, bukan koma." },
  { unit: 17, bad: "The findings were compelling, and it persuaded the sceptical reviewers.", opts: ["it → they","were → was","sceptical → scepticism"], a: 0, ex: "'Findings' is plural, so the pronoun is 'they'.", exId: "'Findings' jamak, jadi kata gantinya 'they'." },
  { unit: 17, bad: "Each student collected their samples, then labelled it carefully.", opts: ["it → them","their → the","collected → collect"], a: 0, ex: "The pronoun must match the plural noun 'samples' → 'them'.", exId: "Kata ganti harus sesuai kata benda jamak 'samples' → 'them'." },
  { unit: 17, bad: "This findings suggest a strong correlation between the two variables.", opts: ["suggest → suggests","This → These","findings → finding"], a: 1, ex: "'Findings' is plural, so the demonstrative determiner must be 'these', not 'this'.", exId: "'Findings' berbentuk jamak, sehingga kata penunjuk harus 'these', bukan 'this'." },
  { unit: 17, bad: "The committee awarded the research grant to my colleague and I.", opts: ["I → me","awarded → rewarded","my colleague → my colleague's"], a: 0, ex: "After the preposition 'to', the object pronoun 'me' is required, not the subject pronoun 'I'.", exId: "Setelah preposisi 'to', diperlukan kata ganti objek 'me', bukan kata ganti subjek 'I'." },
  { unit: 17, bad: "The director and myself attended the international conference in Geneva.", opts: ["\"myself\" → \"I\"","\"myself\" → \"me\"","\"The director and myself\" → \"Myself and the director\""], a: 0, ex: "'Myself' is a reflexive pronoun and cannot act as a subject, so the subject here must be 'I'.", exId: "'Myself' adalah kata ganti refleksif dan tidak dapat berfungsi sebagai subjek, sehingga subjek di sini harus 'I'." },
  { unit: 18, bad: "She bought a wooden beautiful old cabinet at the auction.", opts: ["wooden beautiful old → beautiful old wooden","bought → buy","at the → in the"], a: 0, ex: "Adjective order is opinion–age–material: 'beautiful old wooden'.", exId: "Urutan kata sifat opini–usia–bahan: 'beautiful old wooden'." },
  { unit: 18, bad: "The rapid growth of the digital economy depend on stable investment.", opts: ["depend → depends","rapid → rapidly","stable → stably"], a: 0, ex: "The head noun of the phrase, 'growth', is singular, so the verb is 'depends'.", exId: "Inti frasa, 'growth', bersifat tunggal, jadi kata kerjanya 'depends'." },
  { unit: 18, bad: "The architect designed a glass striking modern façade for the tower.", opts: ["designed → has designed","façade → façades","a glass striking modern → a striking modern glass"], a: 2, ex: "Adjective order is opinion–age–material, so it must be 'a striking modern glass façade'.", exId: "Urutan kata sifat adalah opini–usia–bahan, sehingga menjadi 'a striking modern glass façade'." },
  { unit: 18, bad: "The researchers measured the pollution air levels in several major cities.", opts: ["measured → measures","pollution air levels → air pollution levels","cities → city"], a: 1, ex: "In a noun + noun compound the first noun modifies the second, so it is 'air pollution', not 'pollution air'.", exId: "Dalam gabungan nomina + nomina, nomina pertama menerangkan nomina kedua, sehingga menjadi 'air pollution', bukan 'pollution air'." },
  { unit: 18, bad: "The museum displayed a Chinese ancient bronze sculpture.", opts: ["\"Chinese ancient bronze\" → \"ancient Chinese bronze\"","\"Chinese ancient bronze\" → \"ancient bronze Chinese\"","\"Chinese ancient bronze\" → \"bronze ancient Chinese\""], a: 0, ex: "Adjective order places age before origin before material: 'ancient' (age), 'Chinese' (origin), 'bronze' (material).", exId: "Urutan kata sifat adalah usia sebelum asal sebelum bahan: 'ancient' (usia), 'Chinese' (asal), 'bronze' (bahan)." },
  { unit: 19, bad: "Why the government did not intervene sooner in the crisis?", opts: ["the government did not intervene → did the government not intervene","sooner → soon","in the → on the"], a: 0, ex: "A direct question inverts the auxiliary and subject: 'did the government (not) intervene'.", exId: "Pertanyaan langsung membalik bantu dan subjek: 'did the government (not) intervene'." },
  { unit: 19, bad: "The results were conclusive, weren't it?", opts: ["weren't it → weren't they","were → was","conclusive → conclusively"], a: 0, ex: "The tag pronoun must match the subject 'results' → 'they'.", exId: "Kata ganti pada tag harus sesuai subjek 'results' → 'they'." },
  { unit: 19, bad: "I wonder how did the committee reach such a controversial decision.", opts: ["did the committee reach → the committee reached","I wonder → I wondered","how → what"], a: 0, ex: "An embedded (indirect) question uses statement word order, so drop the auxiliary 'did' and keep the subject before the verb.", exId: "Pertanyaan tidak langsung menggunakan urutan kata pernyataan, jadi hapus kata bantu 'did' dan letakkan subjek sebelum verba." },
  { unit: 19, bad: "The proposal will require substantial funding, doesn't it?", opts: ["doesn't it → won't it","doesn't it → isn't it","doesn't it → won't they"], a: 0, ex: "A question tag must repeat the auxiliary of the statement, so 'will' takes 'won't', and the pronoun for 'the proposal' is 'it'.", exId: "Question tag harus mengulang kata bantu dari pernyataan, sehingga 'will' menjadi 'won't', dan kata ganti untuk 'the proposal' adalah 'it'." },
  { unit: 19, bad: "Could you tell me where can I find the latest statistics?", opts: ["where can I find → where I can find","Could you tell → Can you told","the latest → latest"], a: 0, ex: "In an indirect (embedded) question, use statement word order with the subject before the verb, so there is no auxiliary inversion.", exId: "Dalam pertanyaan tidak langsung (embedded), gunakan urutan kalimat pernyataan dengan subjek sebelum kata kerja, sehingga tidak ada pembalikan kata bantu." },
  { unit: 20, bad: "The course develops reading, writing, and to listen effectively.", opts: ["to listen → listening","develops → develop","effectively → effective"], a: 0, ex: "List items must be parallel: reading, writing, and listening.", exId: "Item dalam daftar harus paralel: reading, writing, and listening." },
  { unit: 20, bad: "The factors include: cost, time, and quality.", opts: ["include: → include","cost, time, → cost; time;","quality. → quality"], a: 0, ex: "Don't put a colon after an incomplete clause ('The factors include').", exId: "Jangan letakkan titik dua setelah klausa tak lengkap ('The factors include')." },
  { unit: 20, bad: "The initial trial was inconclusive, however, the researchers remained optimistic.", opts: ["inconclusive, however → inconclusive; however","however, the → however the","researchers remained → researchers remain"], a: 0, ex: "A conjunctive adverb like 'however' joining two independent clauses needs a semicolon before it, not a comma, to avoid a comma splice.", exId: "Adverbia penghubung seperti 'however' yang menggabungkan dua klausa independen memerlukan titik koma sebelumnya, bukan koma, agar tidak terjadi comma splice." },
  { unit: 20, bad: "The organisation revised it's strategic priorities after the merger.", opts: ["it's → its","revised → revised the","priorities → priority's"], a: 0, ex: "'Its' is the possessive determiner, while 'it's' is only a contraction of 'it is', so no apostrophe is used here.", exId: "'Its' adalah kata ganti milik, sedangkan 'it's' hanya singkatan dari 'it is', jadi tidak menggunakan apostrof di sini." },
  { unit: 20, bad: "The internship taught her to analyse data, to write reports, and communicating with clients.", opts: ["communicating → to communicate","to analyse → analysing","to write reports → writing reports"], a: 0, ex: "Items in a list must share the same grammatical form, so the third item needs the same to-infinitive as the first two.", exId: "Butir-butir dalam sebuah daftar harus memiliki bentuk gramatikal yang sama, sehingga butir ketiga perlu bentuk to-infinitive seperti dua butir pertama." },
  { unit: 21, bad: "Never I had encountered such a comprehensive dataset before.", opts: ["Never I had → Never had I","such a → such","before → ago"], a: 0, ex: "After a fronted negative ('Never'), invert the subject and auxiliary: 'Never had I'.", exId: "Setelah kata negatif di depan ('Never'), balik subjek dan bantu: 'Never had I'." },
  { unit: 21, bad: "So the evidence was compelling that the panel reached a swift verdict.", opts: ["So the evidence was compelling → So compelling was the evidence","reached → reach","swift → swiftly"], a: 0, ex: "The 'so ... that' emphasis fronts the adjective and inverts: 'So compelling was the evidence'.", exId: "Penekanan 'so ... that' menaruh kata sifat di depan dan membalik: 'So compelling was the evidence'." },
  { unit: 21, bad: "The organisation had its financial records to audit by an external firm.", opts: ["to audit → audited","had → made","its → their"], a: 0, ex: "The passive causative 'have something done' requires a past participle, so 'to audit' becomes 'audited'.", exId: "Kausatif pasif 'have something done' memerlukan bentuk past participle, sehingga 'to audit' menjadi 'audited'." },
  { unit: 21, bad: "The committee demanded that the contractor compensates the affected residents.", opts: ["compensates → compensate","demanded → demands","that → whether"], a: 0, ex: "After a mandative verb such as 'demand that', the verb takes the base subjunctive form, so 'compensates' becomes 'compensate'.", exId: "Setelah verba seperti 'demand that', verba menggunakan bentuk dasar subjungtif, sehingga 'compensates' menjadi 'compensate'." },
  { unit: 21, bad: "Not only the company reduced its costs, but it also improved its service.", opts: ["Not only the company reduced → Not only did the company reduce","but it also improved → but also it improved","Not only the company reduced → Not only the company did reduce"], a: 0, ex: "When a negative expression such as 'Not only' begins a clause, invert the subject and auxiliary: 'Not only did the company reduce...'.", exId: "Ketika ungkapan negatif seperti 'Not only' mengawali klausa, balik urutan subjek dan kata bantu: 'Not only did the company reduce...'." },
];

export const TRANSFORM = [
  { unit: 1, instruction: "Add the correct articles.", instructionId: "Tambahkan artikel yang tepat.", original: "Committee approved comprehensive plan to protect environment.", answer: "The committee approved a comprehensive plan to protect the environment.", alts: [], tip: "Specific/unique nouns take 'the'; a new singular countable noun takes 'a'.", tipId: "Kata benda spesifik/unik memakai 'the'; benda tunggal baru memakai 'a'." },
  { unit: 1, instruction: "Rewrite the sentence, adding articles (a/an/the) where they are needed.", instructionId: "Tulis ulang kalimat, tambahkan artikel (a/an/the) di tempat yang diperlukan.", original: "Minister announced new policy to reduce carbon emissions across country.", answer: "The minister announced a new policy to reduce carbon emissions across the country.", alts: ["A minister announced a new policy to reduce carbon emissions across the country."], tip: "Use 'a/an' for a first, non-specific singular noun, 'the' for something specific or unique, and no article for general uncountables and plurals.", tipId: "Gunakan 'a/an' untuk kata benda tunggal yang pertama disebut dan tidak spesifik, 'the' untuk sesuatu yang spesifik atau unik, dan tanpa artikel untuk kata benda tak terhitung dan jamak yang bersifat umum." },
  { unit: 1, instruction: "Insert articles (a/an/the) where they are needed; leave general or uncountable nouns without an article.", instructionId: "Sisipkan artikel (a/an/the) di tempat yang diperlukan; biarkan kata benda umum atau tak terhitung tanpa artikel.", original: "Researcher published groundbreaking study on effects of climate change on coral reefs.", answer: "A researcher published a groundbreaking study on the effects of climate change on coral reefs.", alts: ["The researcher published a groundbreaking study on the effects of climate change on coral reefs."], tip: "Use 'a/an' for a first mention, 'the' for a noun made specific by a following 'of' phrase, and no article for uncountable or general plural nouns.", tipId: "Gunakan 'a/an' untuk penyebutan pertama, 'the' untuk kata benda yang dispesifikkan oleh frasa 'of' setelahnya, dan tanpa artikel untuk kata benda tak terhitung atau jamak umum." },
  { unit: 2, instruction: "Correct the quantifiers and uncountable nouns.", instructionId: "Perbaiki kuantifier dan kata benda tak terhitung.", original: "He gave me a useful advices about many equipments.", answer: "He gave me useful advice about a lot of equipment.", alts: ["He gave me some useful advice about the equipment."], tip: "'Advice' and 'equipment' are uncountable — no plural and no 'a'.", tipId: "'Advice' dan 'equipment' tak terhitung — tanpa jamak dan tanpa 'a'." },
  { unit: 2, instruction: "Rewrite the sentence, correcting the countable/uncountable noun errors.", instructionId: "Tulis ulang kalimat, perbaiki kesalahan kata benda yang dapat/tidak dapat dihitung.", original: "The lecturer shared some interesting researches and gave us many homeworks.", answer: "The lecturer shared some interesting research and gave us a lot of homework.", alts: ["The lecturer shared some interesting research and gave us much homework."], tip: "Uncountable nouns like 'research' and 'homework' have no plural form and take 'much' or 'a lot of', not 'many'.", tipId: "Kata benda tak terhitung seperti 'research' dan 'homework' tidak memiliki bentuk jamak dan menggunakan 'much' atau 'a lot of', bukan 'many'." },
  { unit: 2, instruction: "Rewrite the sentence to correct the uncountable-noun error, using a partitive phrase to express the quantity.", instructionId: "Tulis ulang kalimat untuk memperbaiki kesalahan kata benda tak terhitung, dengan menggunakan frasa partitif untuk menyatakan jumlahnya.", original: "The travellers carried too many luggages through the crowded airport terminal.", answer: "The travellers carried too many pieces of luggage through the crowded airport terminal.", alts: ["The travellers carried too much luggage through the crowded airport terminal."], tip: "'Luggage' is uncountable, so use 'much' or a partitive such as 'pieces of luggage' rather than a plural with 'many'.", tipId: "'Luggage' bersifat tak terhitung, jadi gunakan 'much' atau frasa partitif seperti 'pieces of luggage', bukan bentuk jamak dengan 'many'." },
  { unit: 3, instruction: "Insert the correct prepositions.", instructionId: "Sisipkan preposisi yang tepat.", original: "The report focuses the increase pollution and its impact health.", answer: "The report focuses on the increase in pollution and its impact on health.", alts: [], tip: "focus on · an increase in · an impact on.", tipId: "focus on · an increase in · an impact on." },
  { unit: 3, instruction: "Rewrite the sentence, adding the correct dependent prepositions.", instructionId: "Tulis ulang kalimat, tambahkan preposisi bergantung yang tepat.", original: "The committee is responsible ensuring compliance the new regulations.", answer: "The committee is responsible for ensuring compliance with the new regulations.", alts: [], tip: "Learn dependent prepositions as fixed pairs, such as 'responsible for' and 'compliance with'.", tipId: "Pelajari preposisi bergantung sebagai pasangan tetap, seperti 'responsible for' dan 'compliance with'." },
  { unit: 3, instruction: "Insert the correct dependent prepositions so that the sentence is grammatically complete.", instructionId: "Sisipkan preposisi bergantung yang tepat agar kalimat menjadi lengkap secara tata bahasa.", original: "Scientists are searching a solution the problem of plastic pollution.", answer: "Scientists are searching for a solution to the problem of plastic pollution.", alts: [], tip: "Learn verbs and nouns together with their prepositions as fixed chunks: 'search for' and 'a solution to'.", tipId: "Pelajari kata kerja dan kata benda beserta preposisinya sebagai satu kesatuan tetap: 'search for' dan 'a solution to'." },
  { unit: 4, instruction: "Rewrite as one sentence using a comparative with 'than'.", instructionId: "Tulis ulang jadi satu kalimat dengan komparatif memakai 'than'.", original: "The new policy is efficient. The old policy is not efficient.", answer: "The new policy is more efficient than the old one.", alts: ["The new policy is more efficient than the old policy."], tip: "Use 'more + adjective + than' to compare two things.", tipId: "Pakai 'more + kata sifat + than' untuk membandingkan dua hal." },
  { unit: 4, instruction: "Rewrite the sentence using a superlative form.", instructionId: "Tulis ulang kalimat menggunakan bentuk superlatif.", original: "No other renewable source is as reliable as geothermal energy in this region.", answer: "Geothermal energy is the most reliable renewable source in this region.", alts: ["In this region, geothermal energy is the most reliable renewable source."], tip: "When one thing surpasses all others, express it with 'the most + adjective'.", tipId: "Ketika satu hal mengungguli semua yang lain, ungkapkan dengan 'the most + kata sifat'." },
  { unit: 4, instruction: "Rewrite the sentence using the \"the + comparative ..., the + comparative ...\" structure.", instructionId: "Tulis ulang kalimat menggunakan struktur \"the + komparatif ..., the + komparatif ...\".", original: "As cities grow larger, their transport systems become more congested.", answer: "The larger cities grow, the more congested their transport systems become.", alts: ["The larger a city grows, the more congested its transport system becomes."], tip: "Begin each clause with \"the + comparative\" to show that the two things change together.", tipId: "Mulailah setiap klausa dengan \"the + komparatif\" untuk menunjukkan bahwa kedua hal itu berubah bersamaan." },
  { unit: 5, instruction: "Make the verb agree with the subject.", instructionId: "Sesuaikan kata kerja dengan subjek.", original: "Neither the report nor the appendices was submitted on time.", answer: "Neither the report nor the appendices were submitted on time.", alts: [], tip: "With 'neither/nor', the verb agrees with the nearer subject ('appendices' → plural).", tipId: "Dengan 'neither/nor', kata kerja mengikuti subjek terdekat ('appendices' → jamak)." },
  { unit: 5, instruction: "Rewrite the sentence beginning with 'Neither of' and adjust the verb accordingly.", instructionId: "Tulis ulang kalimat dimulai dengan 'Neither of' dan sesuaikan kata kerjanya.", original: "Both proposals fail to address the budget concerns.", answer: "Neither of the proposals addresses the budget concerns.", alts: ["Neither of the two proposals addresses the budget concerns."], tip: "'Neither of' + a plural noun takes a singular verb in formal English.", tipId: "'Neither of' + kata benda jamak memakai kata kerja tunggal dalam bahasa Inggris formal." },
  { unit: 5, instruction: "Rewrite the sentence starting with \"Each of\" and make the verb agree with the new subject.", instructionId: "Tulis ulang kalimat yang dimulai dengan \"Each of\" dan sesuaikan kata kerjanya dengan subjek baru.", original: "All the volunteers submit a detailed report every month.", answer: "Each of the volunteers submits a detailed report every month.", alts: [], tip: "\"Each of\" + a plural noun is treated as singular, so add -s to the verb.", tipId: "\"Each of\" + kata benda jamak dianggap tunggal, jadi tambahkan -s pada kata kerja." },
  { unit: 6, instruction: "Combine using the past perfect for the earlier action.", instructionId: "Gabungkan memakai past perfect untuk tindakan yang lebih dulu.", original: "The negotiations collapsed. Then the shares fell.", answer: "The shares fell after the negotiations had collapsed.", alts: ["After the negotiations had collapsed, the shares fell."], tip: "The earlier of two past actions takes 'had + past participle'.", tipId: "Tindakan yang lebih dulu memakai 'had + past participle'." },
  { unit: 6, instruction: "Combine the two sentences using the past continuous and past simple to show an interrupted action.", instructionId: "Gabungkan kedua kalimat menggunakan past continuous dan past simple untuk menunjukkan aksi yang terinterupsi.", original: "The researchers were conducting the final trial. The equipment suddenly malfunctioned.", answer: "The researchers were conducting the final trial when the equipment suddenly malfunctioned.", alts: ["While the researchers were conducting the final trial, the equipment suddenly malfunctioned."], tip: "Use the past continuous for the longer background action and the past simple for the sudden event that interrupts it.", tipId: "Gunakan past continuous untuk aksi latar yang berlangsung lama dan past simple untuk peristiwa mendadak yang menyelanya." },
  { unit: 6, instruction: "Combine the two sentences into one using the past perfect continuous to emphasise how long the first action had been going on before the second event.", instructionId: "Gabungkan kedua kalimat menjadi satu menggunakan past perfect continuous untuk menekankan berapa lama tindakan pertama telah berlangsung sebelum peristiwa kedua.", original: "The negotiators discussed the terms for six hours. They finally reached an agreement.", answer: "The negotiators had been discussing the terms for six hours before they finally reached an agreement.", alts: ["The negotiators had been discussing the terms for six hours when they finally reached an agreement."], tip: "Use \"had been + V-ing\" for the longer background action and the past simple for the event that ended it.", tipId: "Gunakan \"had been + V-ing\" untuk tindakan latar yang lebih lama dan past simple untuk peristiwa yang mengakhirinya." },
  { unit: 7, instruction: "Rewrite in the present perfect continuous.", instructionId: "Tulis ulang dalam present perfect continuous.", original: "She started analysing the samples two hours ago and is still analysing them.", answer: "She has been analysing the samples for two hours.", alts: [], tip: "Use 'have/has been + -ing' for an action continuing up to now.", tipId: "Pakai 'have/has been + -ing' untuk tindakan yang berlanjut hingga kini." },
  { unit: 7, instruction: "Rewrite the clause after 'but' using the present continuous to show a temporary situation happening now.", instructionId: "Tulis ulang klausa setelah 'but' menggunakan present continuous untuk menunjukkan situasi sementara yang sedang terjadi sekarang.", original: "The firm usually outsources its logistics, but at present it handles deliveries in-house.", answer: "The firm usually outsources its logistics, but at present it is handling deliveries in-house.", alts: [], tip: "Use the present continuous (am/is/are + -ing) for temporary actions in progress now, often signalled by 'at present'.", tipId: "Gunakan present continuous (am/is/are + -ing) untuk tindakan sementara yang sedang berlangsung sekarang, sering ditandai 'at present'." },
  { unit: 7, instruction: "Rewrite using the present perfect with 'just', keeping the result relevant to now.", instructionId: "Tulis ulang menggunakan present perfect dengan 'just', dengan mempertahankan hasil yang masih relevan sekarang.", original: "The government released the new figures a moment ago.", answer: "The government has just released the new figures.", alts: ["The government has just published the new figures."], tip: "For a very recent action still relevant now, use 'has/have just + past participle' instead of the past simple.", tipId: "Untuk tindakan yang baru saja terjadi dan masih relevan sekarang, gunakan 'has/have just + past participle', bukan past simple." },
  { unit: 8, instruction: "Rewrite using the future perfect.", instructionId: "Tulis ulang memakai future perfect.", original: "They will complete the audit before the deadline.", answer: "They will have completed the audit by the deadline.", alts: [], tip: "Future perfect ('will have + past participle') marks completion before a future point.", tipId: "Future perfect ('will have + past participle') menandai selesai sebelum titik di masa depan." },
  { unit: 8, instruction: "Rewrite in the future continuous to show the action will be in progress at that future time.", instructionId: "Tulis ulang dalam future continuous untuk menunjukkan tindakan yang sedang berlangsung pada waktu depan tersebut.", original: "This time tomorrow, the negotiators discuss the final terms of the merger.", answer: "This time tomorrow, the negotiators will be discussing the final terms of the merger.", alts: [], tip: "Use the future continuous (will be + -ing) for an action already in progress at a definite future moment.", tipId: "Gunakan future continuous (will be + -ing) untuk tindakan yang sudah berlangsung pada saat tertentu di masa depan." },
  { unit: 8, instruction: "Rewrite using 'be going to' to express a plan or decision already made.", instructionId: "Tulis ulang menggunakan 'be going to' untuk menyatakan rencana atau keputusan yang sudah dibuat.", original: "The board has decided to expand into the Asian market next year.", answer: "The board is going to expand into the Asian market next year.", alts: ["Next year, the board is going to expand into the Asian market."], tip: "Use 'be going to + base verb' for a decision or plan already made before the moment of speaking.", tipId: "Gunakan 'be going to + kata kerja dasar' untuk keputusan atau rencana yang sudah diputuskan sebelum berbicara." },
  { unit: 9, instruction: "Rewrite in the passive voice.", instructionId: "Tulis ulang dalam kalimat pasif.", original: "The auditors scrutinised the accounts.", answer: "The accounts were scrutinised by the auditors.", alts: ["The accounts were scrutinised."], tip: "Object becomes subject; verb → 'be + past participle'; the agent takes 'by'.", tipId: "Objek jadi subjek; kata kerja → 'be + past participle'; pelaku memakai 'by'." },
  { unit: 9, instruction: "Rewrite in the passive voice, keeping the present perfect tense.", instructionId: "Tulis ulang dalam bentuk pasif, tetap dalam tense present perfect.", original: "Researchers have identified a promising new compound.", answer: "A promising new compound has been identified.", alts: ["A promising new compound has been identified by researchers."], tip: "Make the object the new subject and use has/have been + past participle; the agent ('by researchers') is optional.", tipId: "Jadikan objek sebagai subjek baru dan gunakan has/have been + past participle; pelaku ('by researchers') bersifat opsional." },
  { unit: 9, instruction: "Rewrite in the passive voice, omitting the agent.", instructionId: "Tulis ulang dalam kalimat pasif, dengan menghilangkan pelakunya.", original: "The authorities will announce the results next week.", answer: "The results will be announced next week.", alts: ["Next week, the results will be announced."], tip: "For a future passive, use 'will be + past participle', and drop the agent when it is obvious or unimportant.", tipId: "Untuk kalimat pasif masa depan, gunakan 'will be + past participle', dan hilangkan pelaku bila sudah jelas atau tidak penting." },
  { unit: 10, instruction: "Rewrite as a second (unreal) conditional.", instructionId: "Tulis ulang sebagai conditional tipe 2 (tidak nyata).", original: "I don't have the data, so I can't reach a conclusion.", answer: "If I had the data, I could reach a conclusion.", alts: ["If I had the data, I would reach a conclusion."], tip: "Second conditional: 'If + past simple, would/could + base verb'.", tipId: "Conditional tipe 2: 'If + past simple, would/could + kata kerja dasar'." },
  { unit: 10, instruction: "Rewrite as a third conditional sentence (an unreal situation in the past).", instructionId: "Tulis ulang sebagai kalimat pengandaian ketiga (situasi tidak nyata di masa lampau).", original: "The committee didn't review the proposal carefully, so they overlooked the crucial flaw.", answer: "If the committee had reviewed the proposal carefully, they would not have overlooked the crucial flaw.", alts: ["Had the committee reviewed the proposal carefully, they would not have overlooked the crucial flaw."], tip: "For an unreal past, use 'if + past perfect' in the condition and 'would have + past participle' in the result.", tipId: "Untuk masa lampau yang tidak nyata, gunakan 'if + past perfect' pada klausa syarat dan 'would have + past participle' pada klausa hasil." },
  { unit: 10, instruction: "Rewrite as a mixed conditional (past condition, present result).", instructionId: "Tulis ulang sebagai mixed conditional (kondisi lampau, hasil sekarang).", original: "The firm did not diversify its investments, so it is now vulnerable to the economic downturn.", answer: "If the firm had diversified its investments, it would not be so vulnerable to the economic downturn now.", alts: ["If the firm had diversified its investments, it would not be vulnerable to the economic downturn now."], tip: "Use \"If + had + past participle\" for the past condition and \"would + base verb\" for the present result.", tipId: "Gunakan \"If + had + past participle\" untuk kondisi lampau dan \"would + kata kerja dasar\" untuk hasil sekarang." },
  { unit: 11, instruction: "Rewrite to express near-certainty about the past.", instructionId: "Tulis ulang untuk menyatakan hampir pasti tentang masa lalu.", original: "I'm sure she didn't receive the message.", answer: "She can't have received the message.", alts: ["She couldn't have received the message."], tip: "'can't have + past participle' shows near-certainty that something did not happen.", tipId: "'can't have + past participle' menunjukkan hampir pasti sesuatu tidak terjadi." },
  { unit: 11, instruction: "Rewrite using a modal of deduction to express near-certainty about a past event.", instructionId: "Tulis ulang menggunakan modal deduksi untuk menyatakan keyakinan hampir pasti tentang kejadian masa lampau.", original: "I'm certain the technicians made an error during the calibration.", answer: "The technicians must have made an error during the calibration.", alts: [], tip: "For a confident conclusion about the past, use 'must have + past participle'.", tipId: "Untuk kesimpulan yang meyakinkan tentang masa lampau, gunakan 'must have + past participle'." },
  { unit: 11, instruction: "Rewrite as advice using an appropriate modal verb.", instructionId: "Tulis ulang sebagai saran menggunakan modal verb yang sesuai.", original: "It would be a good idea for the committee to consult an independent expert.", answer: "The committee should consult an independent expert.", alts: ["The committee ought to consult an independent expert."], tip: "Use \"should\" (or \"ought to\") followed by the base verb to give advice.", tipId: "Gunakan \"should\" (atau \"ought to\") diikuti kata kerja dasar untuk memberikan saran." },
  { unit: 12, instruction: "Combine into one sentence with a relative clause.", instructionId: "Gabungkan jadi satu kalimat dengan klausa relatif.", original: "The professor won an award. She led the research.", answer: "The professor who led the research won an award.", alts: ["The professor, who led the research, won an award."], tip: "Join with 'who' for a person who does the action.", tipId: "Gabungkan dengan 'who' untuk orang yang melakukan tindakan." },
  { unit: 12, instruction: "Combine the two sentences using a non-defining relative clause.", instructionId: "Gabungkan kedua kalimat menggunakan klausa relatif non-defining (tidak membatasi).", original: "The new national stadium cost over two billion dollars. It was completed last year.", answer: "The new national stadium, which was completed last year, cost over two billion dollars.", alts: [], tip: "Add extra, non-essential information with a relative clause set off by commas, using 'which' for things.", tipId: "Tambahkan informasi tambahan yang tidak esensial dengan klausa relatif yang dipisahkan koma, menggunakan 'which' untuk benda." },
  { unit: 12, instruction: "Rewrite the sentence by reducing the relative clause (omit the relative pronoun and the auxiliary).", instructionId: "Tulis ulang kalimat dengan meringkas relative clause (hilangkan kata ganti relatif dan kata kerja bantu).", original: "The proposals that were submitted after the deadline were automatically disqualified.", answer: "The proposals submitted after the deadline were automatically disqualified.", alts: [], tip: "When a relative clause is passive, drop \"that/which + be\" and keep the past participle.", tipId: "Ketika relative clause berbentuk pasif, hapus \"that/which + be\" dan pertahankan past participle." },
  { unit: 13, instruction: "Combine using 'although'.", instructionId: "Gabungkan memakai 'although'.", original: "The sample was small. The findings were significant.", answer: "Although the sample was small, the findings were significant.", alts: ["The findings were significant although the sample was small."], tip: "'Although + clause' shows contrast; add a comma when it comes first.", tipId: "'Although + klausa' menunjukkan kontras; beri koma bila di depan." },
  { unit: 13, instruction: "Combine into one complex sentence using 'because' to show cause.", instructionId: "Gabungkan menjadi satu kalimat kompleks menggunakan 'because' untuk menunjukkan sebab.", original: "The results were inconclusive. The committee postponed its decision.", answer: "The committee postponed its decision because the results were inconclusive.", alts: ["Because the results were inconclusive, the committee postponed its decision."], tip: "Put 'because' before the cause; if the because-clause comes first, add a comma before the main clause.", tipId: "Letakkan 'because' sebelum penyebab; jika klausa 'because' berada di awal, tambahkan koma sebelum klausa utama." },
  { unit: 13, instruction: "Combine the two sentences into one complex sentence using 'because' to show cause and effect.", instructionId: "Gabungkan kedua kalimat menjadi satu kalimat kompleks menggunakan 'because' untuk menunjukkan sebab dan akibat.", original: "The supplier raised its prices sharply. Several retailers switched to a cheaper competitor.", answer: "Because the supplier raised its prices sharply, several retailers switched to a cheaper competitor.", alts: ["Several retailers switched to a cheaper competitor because the supplier raised its prices sharply."], tip: "Place 'because' before the cause; when the cause clause comes first, separate it from the main clause with a comma.", tipId: "Letakkan 'because' sebelum penyebab; jika klausa penyebab berada di depan, pisahkan dari klausa utama dengan koma." },
  { unit: 14, instruction: "Rewrite starting with the gerund as the subject.", instructionId: "Tulis ulang mulai dengan gerund sebagai subjek.", original: "It is essential to acquire new skills.", answer: "Acquiring new skills is essential.", alts: [], tip: "A gerund (-ing) can act as the subject and takes a singular verb.", tipId: "Gerund (-ing) bisa menjadi subjek dan memakai kata kerja tunggal." },
  { unit: 14, instruction: "Rewrite using the pattern 'succeed in + gerund' to express the same idea.", instructionId: "Tulis ulang menggunakan pola 'succeed in + gerund' untuk menyampaikan makna yang sama.", original: "The team managed to reduce operating costs significantly.", answer: "The team succeeded in reducing operating costs significantly.", alts: [], tip: "After the preposition 'in' (as in 'succeed in'), use the gerund (-ing) form of the verb.", tipId: "Setelah preposisi 'in' (seperti pada 'succeed in'), gunakan bentuk gerund (-ing) dari kata kerja." },
  { unit: 14, instruction: "Combine the two sentences into one using 'by + gerund' to express the method.", instructionId: "Gabungkan kedua kalimat menjadi satu menggunakan 'by + gerund' untuk menyatakan cara/metode.", original: "The firm reduced its emissions. It switched to renewable energy.", answer: "The firm reduced its emissions by switching to renewable energy.", alts: ["By switching to renewable energy, the firm reduced its emissions."], tip: "After the preposition 'by', use the -ing (gerund) form to describe how something is done.", tipId: "Setelah preposisi 'by', gunakan bentuk -ing (gerund) untuk menjelaskan bagaimana sesuatu dilakukan." },
  { unit: 15, instruction: "Report the speech (backshift as needed).", instructionId: "Ubah ke kalimat tak langsung (dengan backshift).", original: "\"I will publish the findings tomorrow,\" she said.", answer: "She said that she would publish the findings the next day.", alts: ["She said she would publish the findings the following day."], tip: "'will' → 'would'; 'tomorrow' → 'the next/following day'.", tipId: "'will' → 'would'; 'tomorrow' → 'the next/following day'." },
  { unit: 15, instruction: "Rewrite as reported speech, beginning with 'The examiner asked...'.", instructionId: "Tulis ulang sebagai kalimat tidak langsung, dimulai dengan 'The examiner asked...'.", original: "\"Have you completed the assessment?\" the examiner asked.", answer: "The examiner asked whether I had completed the assessment.", alts: ["The examiner asked if I had completed the assessment."], tip: "For a yes/no question, use 'if/whether', switch to statement word order, and backshift the tense.", tipId: "Untuk pertanyaan ya/tidak, gunakan 'if/whether', ubah ke urutan kalimat pernyataan, dan geser tense ke bentuk lampau." },
  { unit: 15, instruction: "Rewrite the sentence in reported speech, beginning with 'The accountant said that…'.", instructionId: "Tulis ulang kalimat dalam kalimat tidak langsung (reported speech), dimulai dengan 'The accountant said that…'.", original: "\"I am reviewing the figures now,\" the accountant said.", answer: "The accountant said that he was reviewing the figures then.", alts: ["The accountant said that she was reviewing the figures then."], tip: "Backshift the present continuous to the past continuous, change the pronoun, and shift 'now' to 'then'.", tipId: "Ubah present continuous menjadi past continuous, ganti kata gantinya, dan ubah 'now' menjadi 'then'." },
  { unit: 16, instruction: "Join the two sentences with 'therefore', correctly punctuated.", instructionId: "Gabungkan dua kalimat dengan 'therefore', dengan tanda baca yang benar.", original: "Demand collapsed. Prices fell sharply.", answer: "Demand collapsed; therefore, prices fell sharply.", alts: ["Demand collapsed. Therefore, prices fell sharply."], tip: "Use a semicolon before 'therefore' and a comma after it.", tipId: "Pakai titik koma sebelum 'therefore' dan koma sesudahnya." },
  { unit: 16, instruction: "Combine the two sentences into one using 'despite' followed by a noun phrase.", instructionId: "Gabungkan kedua kalimat menjadi satu menggunakan 'despite' yang diikuti frasa nomina.", original: "The evidence was compelling. The jury remained unconvinced.", answer: "Despite the compelling evidence, the jury remained unconvinced.", alts: ["In spite of the compelling evidence, the jury remained unconvinced."], tip: "'Despite' is a preposition, so follow it with a noun phrase, never a full clause.", tipId: "'Despite' adalah preposisi, jadi ikuti dengan frasa nomina, bukan klausa lengkap." },
  { unit: 16, instruction: "Combine the two sentences into one using 'despite' followed by a noun phrase (not a clause).", instructionId: "Gabungkan kedua kalimat menjadi satu menggunakan 'despite' yang diikuti frasa kata benda (bukan klausa).", original: "The company invested heavily in marketing. Its sales declined.", answer: "Despite its heavy investment in marketing, the company's sales declined.", alts: ["Despite heavy investment in marketing, the company's sales declined.","Despite investing heavily in marketing, the company saw its sales decline."], tip: "'Despite' is a preposition, so follow it with a noun phrase or an -ing form, never a full subject–verb clause.", tipId: "'Despite' adalah preposisi, jadi ikuti dengan frasa kata benda atau bentuk -ing, bukan klausa subjek–predikat lengkap." },
  { unit: 17, instruction: "Replace the repeated noun with a pronoun.", instructionId: "Ganti kata benda yang berulang dengan kata ganti.", original: "The researchers submitted the report, and the researchers defended the report.", answer: "The researchers submitted the report and defended it.", alts: ["They submitted the report and defended it."], tip: "Use 'it' for the singular thing and avoid repeating the subject.", tipId: "Pakai 'it' untuk benda tunggal dan hindari mengulang subjek." },
  { unit: 17, instruction: "Rewrite the sentence, replacing the repeated noun with the substitute pronoun 'one'.", instructionId: "Tulis ulang kalimat, ganti nomina yang diulang dengan kata pengganti 'one'.", original: "The initial prototype was flawed, so the engineers developed a more robust prototype.", answer: "The initial prototype was flawed, so the engineers developed a more robust one.", alts: [], tip: "Use 'one' to replace a previously mentioned singular countable noun and avoid repetition.", tipId: "Gunakan 'one' untuk menggantikan nomina tunggal yang dapat dihitung yang sudah disebutkan agar tidak mengulang." },
  { unit: 17, instruction: "Rewrite to avoid the repeated noun, using the substitute word 'one' in place of it.", instructionId: "Tulis ulang untuk menghindari pengulangan kata benda, gunakan kata substitusi 'one' sebagai penggantinya.", original: "The first hypothesis was rejected, but the second hypothesis was confirmed.", answer: "The first hypothesis was rejected, but the second one was confirmed.", alts: ["The first hypothesis was rejected, but the second was confirmed."], tip: "Use 'one' (or 'ones') to replace a countable noun that has already been mentioned, avoiding clumsy repetition.", tipId: "Gunakan 'one' (atau 'ones') untuk menggantikan kata benda terhitung yang sudah disebutkan, agar tidak mengulang secara janggal." },
  { unit: 18, instruction: "Put the adjectives in the correct order.", instructionId: "Susun kata sifat dalam urutan yang benar.", original: "a cabinet (wooden / compact / elegant)", answer: "an elegant compact wooden cabinet", alts: [], tip: "Order: opinion → size → material (elegant → compact → wooden).", tipId: "Urutan: opini → ukuran → bahan (elegant → compact → wooden)." },
  { unit: 18, instruction: "Rewrite in a more academic style by turning the verb 'reduced' into a noun phrase (nominalisation).", instructionId: "Tulis ulang dengan gaya yang lebih akademis dengan mengubah kata kerja 'reduced' menjadi frasa nomina (nominalisasi).", original: "When the government reduced spending, the economy slowed.", answer: "The government's reduction in spending slowed the economy.", alts: ["The reduction in government spending caused the economy to slow."], tip: "Turn the verb 'reduced' into the noun 'reduction' and make the resulting noun phrase the subject.", tipId: "Ubah kata kerja 'reduced' menjadi nomina 'reduction' dan jadikan frasa nomina itu sebagai subjek." },
  { unit: 18, instruction: "Rewrite using nominalisation so the underlined clause becomes a noun phrase subject: turn the verb into a noun.", instructionId: "Tulis ulang menggunakan nominalisasi sehingga klausa menjadi subjek berupa frasa kata benda: ubah kata kerja menjadi kata benda.", original: "Because the population grew rapidly, the demand for housing increased.", answer: "The rapid growth of the population increased the demand for housing.", alts: ["The rapid population growth increased the demand for housing."], tip: "Turn the action verb into a noun (grow → growth) and build a noun phrase to create a more formal, academic subject.", tipId: "Ubah kata kerja aksi menjadi kata benda (grow → growth) dan bentuk frasa kata benda untuk membuat subjek yang lebih formal dan akademis." },
  { unit: 19, instruction: "Add a correct question tag.", instructionId: "Tambahkan question tag yang benar.", original: "The proposal was rejected.", answer: "The proposal was rejected, wasn't it?", alts: [], tip: "A positive statement takes a negative tag matching the auxiliary and subject.", tipId: "Pernyataan positif memakai tag negatif yang sesuai bantu dan subjek." },
  { unit: 19, instruction: "Rewrite as an indirect question, beginning with 'Do you know'.", instructionId: "Tulis ulang sebagai pertanyaan tidak langsung, dimulai dengan 'Do you know'.", original: "When will the authorities announce the new regulations?", answer: "Do you know when the authorities will announce the new regulations?", alts: ["Do you know when the new regulations will be announced?"], tip: "After the wh-word in an indirect question, use statement order (subject before auxiliary and verb) instead of question inversion.", tipId: "Setelah kata tanya dalam pertanyaan tidak langsung, gunakan urutan pernyataan (subjek sebelum kata bantu dan verba), bukan pembalikan seperti pada pertanyaan langsung." },
  { unit: 19, instruction: "Rewrite as an indirect question beginning with 'Could you explain...'.", instructionId: "Tulis ulang menjadi pertanyaan tidak langsung yang dimulai dengan 'Could you explain...'.", original: "How does the algorithm process such vast quantities of data?", answer: "Could you explain how the algorithm processes such vast quantities of data?", alts: [], tip: "In indirect questions, drop the auxiliary do/does/did and put the verb in statement order.", tipId: "Dalam pertanyaan tidak langsung, hilangkan kata bantu do/does/did dan gunakan urutan kata seperti kalimat pernyataan." },
  { unit: 20, instruction: "Rewrite the list so it is parallel.", instructionId: "Tulis ulang daftar agar paralel.", original: "The programme is cheap, effective, and it saves time.", answer: "The programme is cheap, effective, and time-saving.", alts: ["The programme is cheap, effective, and efficient."], tip: "Keep list items in the same grammatical form (all adjectives).", tipId: "Jaga item daftar dalam bentuk gramatikal yang sama (semua kata sifat)." },
  { unit: 20, instruction: "Rewrite as one sentence, using a semicolon to join the two independent clauses.", instructionId: "Tulis ulang menjadi satu kalimat, gunakan titik koma untuk menggabungkan dua klausa independen.", original: "The negotiations were protracted. The final agreement satisfied nobody.", answer: "The negotiations were protracted; the final agreement satisfied nobody.", alts: [], tip: "A semicolon links two closely related independent clauses without a conjunction; do not capitalise the word after it.", tipId: "Titik koma menghubungkan dua klausa independen yang berkaitan erat tanpa kata sambung; jangan menggunakan huruf kapital pada kata setelahnya." },
  { unit: 20, instruction: "Rewrite the sentence so the three items are grammatically parallel.", instructionId: "Tulis ulang kalimat agar ketiga butirnya sejajar secara gramatikal.", original: "The report was praised for being thorough, accurate, and it was concise.", answer: "The report was praised for being thorough, accurate, and concise.", alts: [], tip: "Make every item in a series the same grammatical form; here, all three should be adjectives.", tipId: "Buat setiap butir dalam rangkaian memiliki bentuk gramatikal yang sama; di sini ketiganya harus kata sifat." },
  { unit: 21, instruction: "Rewrite with inversion, starting with 'Not only'.", instructionId: "Tulis ulang dengan inversi, mulai dengan 'Not only'.", original: "The reform was expensive and it was slow.", answer: "Not only was the reform expensive, but it was also slow.", alts: ["Not only was the reform expensive, but it was slow as well."], tip: "After a fronted 'Not only', invert the subject and auxiliary.", tipId: "Setelah 'Not only' di depan, balik subjek dan bantu." },
  { unit: 21, instruction: "Rewrite for emphasis, beginning with 'Not only'.", instructionId: "Tulis ulang untuk penekanan, dimulai dengan 'Not only'.", original: "The initiative reduced costs, and it improved efficiency.", answer: "Not only did the initiative reduce costs, but it also improved efficiency.", alts: ["Not only did the initiative reduce costs, but it improved efficiency as well."], tip: "After a fronted 'Not only', invert the subject and auxiliary (did + subject + base verb), then continue with 'but ... also'.", tipId: "Setelah 'Not only' diletakkan di depan, balik subjek dan kata bantu (did + subjek + verba dasar), lalu lanjutkan dengan 'but ... also'." },
  { unit: 21, instruction: "Rewrite using the causative structure 'have + object + past participle', keeping the same meaning.", instructionId: "Tulis ulang menggunakan struktur kausatif 'have + objek + past participle', dengan mempertahankan makna yang sama.", original: "A professional decorator painted their new office over the weekend.", answer: "They had their new office painted by a professional decorator over the weekend.", alts: ["They had their new office painted over the weekend."], tip: "Causative 'have something done' = have + object + past participle; the doer is optional and follows 'by'.", tipId: "Kausatif 'have something done' = have + objek + past participle; pelaku bersifat opsional dan diletakkan setelah 'by'." },
];
